expression:
grel:if(isBlank(value), value,
  with(value.trim(), s,
    if(isNotNull(s.match(/\d{2}\/\d{2}\/\d{4}/)),
      with(s.split("/"), p, p[2] + "-" + p[1] + "-" + p[0]),
      if(isNotNull(s.match(/\d{2}-\d{2}-\d{4}/)),
        with(s.split("-"), p, p[2] + "-" + p[0] + "-" + p[1]),
        if(isNotNull(s.match(/\d{4}\/\d{2}\/\d{2}/)),
          s.replace("/", "-"),
          s
        )
      )
    )
  )
)

