expression:
grel:if(isBlank(value), value,
  with(value.replace(/[^0-9+]/, ""), v,
    if(v.startsWith("0033"),
      "+33" + v.substring(4),
      if(isNotNull(v.match(/0[0-9]{9}/)),
        "+33" + v.substring(1),
        v
      )
    )
  )
)

